/* RuleItem.insertItem */
INSERT INTO RULEITEM(
ITEMID
,ITEM_NM
,ITEMALIAS_NM
,ITEMEXPLAN_DESC
,DATATYPE_CD
,UPDATE_USERID
,UPDATE_DATETIME
,FIRSTREG_USERID
,FIRSTREG_DATETIME
,ITEM_USE_YN
,IFID
)
VALUES(
 #{itemId}
,#{itemNm}
,#{itemAliasNm}
,#{itemExplanDesc}
,#{dataTypeCd}
,NULL
,NULL
,#{firstRegUserId}
,TO_CHAR(SYSDATE, 'YYYYMMDDhh24miss')
,#{itemUseYn}
,#{ifid}
)

mapper.update:
UPDATE RULEITEM
SET ITEM_NM = #{itemNm}
,ITEMALIAS_NM = #{itemAliasNm}
,ITEMEXPLAN_DESC = #{itemExplanDesc}
,DATATYPE_CD = #{dataTypeCd}
,UPDATE_USERID = #{updateUserID}
,UPDATE_DATETIME = TO_CHAR(SYSDATE, 'YYYYMMDDhh24miss')
,ITEM_USE_YN =#{itemUseYn}
,IFID = #{ifid}
WHERE ITEMID = #{itemId}

UPDATE RULEITEMREF SET
    ITEMREF_CD = #{itemrefCd}
    ,ITEMREF_NM = #{itemrefNm}
    ,ITEMREFALIAS_NM = #{itemrefaliasNm}
    ,ITEMREFEXPR_DESC = #{itemrefexprDesc}
    ,UPDATE_USERID = #{updateUserid}
    ,UPDATE_DATETIME = SYSDATE
    WHERE ITEMID = #{itemId}
      and ITEMREF_CD = #{asisInputItemrefCd}

mapper.delete:
DELETE FROM RULEITEMREF
    where ITEMID = #{itemId}
    and ITEMREF_CD = #{itemrefCd}

mapper.select:
select count(*)
from RULEITEMREF
where ITEMID = #{itemid}
and ITEMREF_CD = #{itemrefCd}

select RULEID
from RULECONDITIONRETURNITEM
where RETURN_ITEMID = #{value}

SELECT COUNT(1) AS CNT
  FROM RULEITEM
 WHERE ITEMALIAS_NM = #{itemAliasNm}
   AND IFID = #{ifid}
